// HUD: DOM for stats/feeds/menus, a 2D overlay canvas for viewmodel weapon,
// muzzle flash, tracers, and radar.

import { WEAPONS, ARMOR_PRICE } from './game.js';
import { BOXES, MAT } from './map.js';
import { crosshairCSS, renderCrosshair } from './settings.js';

export class HUD {
  constructor(game, settings) {
    this.game = game;
    this.settings = settings;
    this.canvas = document.getElementById('overlay');
    this.ctx = this.canvas.getContext('2d');
    this.crosshairEl = document.getElementById('crosshair');
    this.tracers = [];   // {x1,y1,x2,y2,t}
    this.flashT = 0;
    this.dmgNumbers = []; // {x,y,t,text,head}
    this.hitmarkerT = 0;
    this.hitmarkerHead = false;
    this.vignetteT = 0;
    this.killfeed = [];
    this.lastWeapon = null;
    this.weaponSwitchT = 0;
  }

  resize() {
    const c = this.canvas;
    if (c.width !== c.clientWidth || c.height !== c.clientHeight) {
      c.width = c.clientWidth;
      c.height = c.clientHeight;
    }
  }

  worldToScreen(p, cam) {
    const rel = [p[0] - cam.pos[0], p[1] - cam.pos[1], p[2] - cam.pos[2]];
    const dz = rel[0] * cam.fwd[0] + rel[1] * cam.fwd[1] + rel[2] * cam.fwd[2];
    if (dz < 0.05) return null;
    const dx = rel[0] * cam.right[0] + rel[1] * cam.right[1] + rel[2] * cam.right[2];
    const dy = rel[0] * cam.up[0] + rel[1] * cam.up[1] + rel[2] * cam.up[2];
    const tanY = Math.tan(cam.fov / 2);
    const aspect = this.canvas.width / this.canvas.height;
    const ndcx = dx / (dz * tanY * aspect);
    const ndcy = dy / (dz * tanY);
    return [
      (ndcx * 0.5 + 0.5) * this.canvas.width,
      (1 - (ndcy * 0.5 + 0.5)) * this.canvas.height,
    ];
  }

  onShot(info, cam) {
    this.flashT = 0.07;
    const def = WEAPONS[info.weapon];
    if (!def.melee) {
      const mx = this.canvas.width * 0.62;
      const my = this.canvas.height * 0.78;
      for (const h of info.hits) {
        const s = this.worldToScreen(h.point, cam);
        if (s) this.tracers.push({ x1: mx, y1: my, x2: s[0], y2: s[1], t: 0.08 });
        if (h.bot && this.settings.get('game.damageNumbers')) {
          const bs = this.worldToScreen([h.point[0], h.point[1] + 0.5, h.point[2]], cam);
          if (bs) this.dmgNumbers.push({ x: bs[0], y: bs[1], t: 0.9, text: `${h.dmg}`, head: h.head });
        }
      }
    }
    if (info.hit) {
      this.hitmarkerT = 0.18;
      this.hitmarkerHead = info.headshot;
    }
  }

  onPlayerDamage() { this.vignetteT = 0.45; }

  addKillfeed(text, head) {
    if (!this.settings.get('game.killFeed')) return;
    this.killfeed.push({ text, head, t: 5 });
    if (this.killfeed.length > 5) this.killfeed.shift();
  }

  updateCrosshair() {
    const g = this.game;
    const spreadPx = Math.round((g.spread + (g.player ? Math.hypot(g.player.vel[0], g.player.vel[2]) * 0.002 : 0)) * 900);
    renderCrosshair(this.crosshairEl, crosshairCSS(this.settings, spreadPx));
    this.crosshairEl.style.display = (g.player && g.player.scoped) ? 'none' : 'block';
  }

  draw(dt, cam) {
    this.resize();
    const ctx = this.ctx;
    const W = this.canvas.width, H = this.canvas.height;
    ctx.clearRect(0, 0, W, H);
    const g = this.game;
    if (!g.player) return;

    // tracers
    this.tracers = this.tracers.filter(t => (t.t -= dt) > 0);
    for (const t of this.tracers) {
      ctx.strokeStyle = `rgba(255, 240, 160, ${t.t / 0.08 * 0.85})`;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(t.x1, t.y1);
      ctx.lineTo(t.x2, t.y2);
      ctx.stroke();
    }

    // damage numbers
    this.dmgNumbers = this.dmgNumbers.filter(d => (d.t -= dt) > 0);
    ctx.textAlign = 'center';
    for (const d of this.dmgNumbers) {
      const k = 1 - d.t / 0.9;
      ctx.font = `bold ${d.head ? 19 : 15}px 'Courier New', monospace`;
      ctx.fillStyle = d.head ? `rgba(255,80,60,${d.t})` : `rgba(255,220,120,${d.t})`;
      ctx.fillText(d.text, d.x, d.y - k * 36);
    }

    // hitmarker
    if (this.hitmarkerT > 0) {
      this.hitmarkerT -= dt;
      const a = Math.max(0, this.hitmarkerT / 0.18);
      ctx.strokeStyle = this.hitmarkerHead ? `rgba(255,60,40,${a})` : `rgba(255,255,255,${a})`;
      ctx.lineWidth = 2;
      const cx = W / 2, cy = H / 2, o = 7, l = 7;
      ctx.beginPath();
      for (const [sx, sy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
        ctx.moveTo(cx + sx * o, cy + sy * o);
        ctx.lineTo(cx + sx * (o + l), cy + sy * (o + l));
      }
      ctx.stroke();
    }

    // viewmodel + muzzle flash
    if (this.settings.get('game.viewmodel') && !g.player.scoped) {
      this.drawViewmodel(ctx, W, H, dt);
    }

    // scope overlay
    if (g.player.scoped) {
      ctx.fillStyle = 'rgba(0,0,0,0.92)';
      const r = Math.min(W, H) * 0.42;
      ctx.beginPath();
      ctx.rect(0, 0, W, H);
      ctx.arc(W / 2, H / 2, r, 0, Math.PI * 2, true);
      ctx.fill();
      ctx.strokeStyle = 'rgba(120,255,210,0.7)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(W / 2 - r, H / 2); ctx.lineTo(W / 2 + r, H / 2);
      ctx.moveTo(W / 2, H / 2 - r); ctx.lineTo(W / 2, H / 2 + r);
      ctx.stroke();
    }

    // radar
    if (this.settings.get('game.radar')) this.drawRadar(ctx);

    // damage vignette
    if (this.vignetteT > 0) {
      this.vignetteT -= dt;
      const a = this.vignetteT / 0.45 * 0.45;
      const grad = ctx.createRadialGradient(W / 2, H / 2, H * 0.3, W / 2, H / 2, H * 0.75);
      grad.addColorStop(0, 'rgba(180,0,0,0)');
      grad.addColorStop(1, `rgba(180,0,0,${a})`);
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, W, H);
    }

    // low hp pulse
    if (g.player.hp <= 30 && g.player.hp > 0) {
      const a = 0.12 + 0.08 * Math.sin(g.time * 6);
      const grad = ctx.createRadialGradient(W / 2, H / 2, H * 0.35, W / 2, H / 2, H * 0.8);
      grad.addColorStop(0, 'rgba(160,0,0,0)');
      grad.addColorStop(1, `rgba(160,0,0,${a})`);
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, W, H);
    }
  }

  drawViewmodel(ctx, W, H, dt) {
    const g = this.game;
    const p = g.player;
    const def = WEAPONS[p.current];
    if (p.current !== this.lastWeapon) { this.lastWeapon = p.current; this.weaponSwitchT = 0.25; }
    if (this.weaponSwitchT > 0) this.weaponSwitchT -= dt;

    const bob = this.settings.get('controls.viewBobbing')
      ? Math.sin(p.bobT * 9) * 6 * Math.min(1, Math.hypot(p.vel[0], p.vel[2]) / 6.4)
      : 0;
    const kick = g.recoil * 14;
    const raise = this.weaponSwitchT > 0 ? this.weaponSwitchT * 240 : 0;
    const reloadDip = p.reloadT > 0 ? Math.sin(Math.min(1, 1 - p.reloadT / (def.reloadTime || 1)) * Math.PI) * 60 : 0;

    const bx = W * 0.62 + Math.cos(p.bobT * 4.5) * 4;
    const by = H * 0.8 + bob + kick + raise + reloadDip;

    ctx.save();
    ctx.translate(bx, by);
    ctx.rotate(-0.06 + g.recoil * -0.05);

    // gun silhouette: barrel, body, grip — proportions vary per weapon
    const L = def.melee ? 60 : (def.scoped ? 170 : def.slot === 0 ? 130 : 85);
    const bodyH = def.melee ? 10 : 26;
    ctx.fillStyle = '#15181f';
    ctx.strokeStyle = '#2c3340';
    ctx.lineWidth = 2;
    if (def.melee) {
      ctx.save();
      ctx.rotate(-0.5);
      ctx.fillStyle = '#aeb6c4';
      ctx.fillRect(0, -52, 9, 46); // blade
      ctx.fillStyle = '#15181f';
      ctx.fillRect(-2, -8, 13, 26); // handle
      ctx.restore();
    } else {
      ctx.fillRect(-30, 0, L, bodyH);          // body+barrel
      ctx.strokeRect(-30, 0, L, bodyH);
      ctx.fillRect(-22, bodyH, 18, 34);         // grip
      ctx.fillRect(8, bodyH, 14, 22);           // mag
      if (def.scoped) {
        ctx.fillRect(10, -14, 52, 12);          // scope
        ctx.strokeRect(10, -14, 52, 12);
      }
      // neon accent
      ctx.fillStyle = '#3dffc8';
      ctx.fillRect(-30, bodyH - 4, L, 2);
    }
    ctx.restore();

    // muzzle flash
    if (this.flashT > 0) {
      this.flashT -= dt;
      const a = this.flashT / 0.07;
      const fx = bx + (def.melee ? 10 : L - 30 + 14);
      const fy = by + 8;
      const grad = ctx.createRadialGradient(fx, fy, 2, fx, fy, 38);
      grad.addColorStop(0, `rgba(255,240,180,${a})`);
      grad.addColorStop(0.4, `rgba(255,160,60,${a * 0.7})`);
      grad.addColorStop(1, 'rgba(255,120,30,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(fx, fy, 38, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  drawRadar(ctx) {
    const g = this.game;
    const size = 130, pad = 14;
    const x0 = pad, y0 = pad;
    ctx.save();
    ctx.globalAlpha = 0.82;
    ctx.fillStyle = 'rgba(8,10,18,0.85)';
    ctx.fillRect(x0, y0, size, size);
    ctx.strokeStyle = 'rgba(61,255,200,0.5)';
    ctx.strokeRect(x0, y0, size, size);

    const scale = size / 88; // world is ~84 wide
    const toMap = (wx, wz) => [x0 + size / 2 + wx * scale, y0 + size / 2 + wz * scale];

    // walls footprint
    ctx.fillStyle = 'rgba(61,255,200,0.16)';
    for (const b of BOXES) {
      if (b[6] === MAT.FLOOR || b[4] < 1.5) continue;
      const [mx, my] = toMap(b[0], b[2]);
      ctx.fillRect(mx, my, (b[3] - b[0]) * scale, (b[5] - b[2]) * scale);
    }
    // bots
    for (const b of g.bots) {
      if (!b.alive) continue;
      const [mx, my] = toMap(b.pos[0], b.pos[2]);
      ctx.fillStyle = '#ff4040';
      ctx.beginPath();
      ctx.arc(mx, my, 3, 0, Math.PI * 2);
      ctx.fill();
    }
    // player (with view direction)
    const p = g.player;
    const [px, py] = toMap(p.pos[0], p.pos[2]);
    ctx.fillStyle = '#3dffc8';
    ctx.beginPath();
    ctx.arc(px, py, 3.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#3dffc8';
    ctx.beginPath();
    ctx.moveTo(px, py);
    ctx.lineTo(px + Math.sin(p.yaw) * 9, py - Math.cos(p.yaw) * 9);
    ctx.stroke();
    ctx.restore();
  }

  // DOM stats panel
  updateDOM() {
    const g = this.game;
    if (!g.player) return;
    setText('hud-hp', Math.max(0, Math.ceil(g.player.hp)));
    setText('hud-armor', Math.ceil(g.player.armor));
    const def = WEAPONS[g.player.current];
    const st = g.player.weapons[g.player.current];
    setText('hud-weapon', def.name);
    setText('hud-ammo', def.melee ? '—' : `${st.ammo} / ${st.reserve}`);
    setText('hud-money', `$${g.money}`);
    setText('hud-round', `R${g.round}`);
    setText('hud-score', `YOU ${g.score.player} : ${g.score.bots} BOTS`);
    const t = Math.max(0, g.phaseT);
    const mm = Math.floor(t / 60), ss = Math.floor(t % 60);
    setText('hud-timer', g.state === 'buy' ? `BUY ${Math.ceil(t)}` : `${mm}:${String(ss).padStart(2, '0')}`);
    document.getElementById('hud-timer').classList.toggle('warn', g.state === 'live' && t < 20);

    const feedEl = document.getElementById('killfeed');
    this.killfeed = this.killfeed.filter(k => (k.t -= 1 / 60) > 0);
    feedEl.innerHTML = this.killfeed
      .map(k => `<div class="feed-entry${k.head ? ' head' : ''}">${k.text}</div>`)
      .join('');
  }
}

export function buildBuyMenu(container, game, onBuy) {
  container.innerHTML = '<h2>BUY MENU <span class="buy-hint">[B] close · buy phase only</span></h2>';
  const grid = document.createElement('div');
  grid.className = 'buy-grid';
  const items = [
    ['pistol', WEAPONS.pistol], ['deagle', WEAPONS.deagle], ['smg', WEAPONS.smg],
    ['shotgun', WEAPONS.shotgun], ['rifle', WEAPONS.rifle], ['sniper', WEAPONS.sniper],
  ];
  for (const [key, def] of items) {
    const card = document.createElement('button');
    card.className = 'buy-card';
    card.dataset.item = key;
    card.innerHTML = `<span class="buy-name">${def.name}</span>
      <span class="buy-stats">DMG ${def.dmg}${def.pellets ? '×' + def.pellets : ''} · RPM ${def.rpm}</span>
      <span class="buy-price">${def.price === 0 ? 'FREE' : '$' + def.price}</span>`;
    card.addEventListener('click', () => onBuy(key));
    grid.appendChild(card);
  }
  const armor = document.createElement('button');
  armor.className = 'buy-card armor';
  armor.dataset.item = 'armor';
  armor.innerHTML = `<span class="buy-name">Kevlar Vest</span>
    <span class="buy-stats">Absorbs 50% damage</span>
    <span class="buy-price">$${ARMOR_PRICE}</span>`;
  armor.addEventListener('click', () => onBuy('armor'));
  grid.appendChild(armor);
  container.appendChild(grid);
}

function setText(id, txt) {
  const el = document.getElementById(id);
  if (el && el.textContent !== String(txt)) el.textContent = txt;
}
